usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Responses.Compact.New(
		context.TODO(),
		openai.ResponseCompactNewParams{
			Model: "string",
			Input: "string",
			PreviousResponseID: param.NewOpt[string]("string"),
			Instructions: param.NewOpt[string]("string"),
			PromptCacheKey: param.NewOpt[string]("string"),
			PromptCacheRetention: openai.PromptCacheRetentionEnumInMemory,
			ServiceTier: openai.ServiceTierEnumAuto,
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
